// CsrTrigger pre-scans an instruction buffer (typically the loadable
// executable segments of an ELF) for the marker HINTs (slti x0, x0,
// 0x5A0/0x5A1) and records their PCs. At retire time the simulator
// queries lookup(pc) to decide whether to drain state at the trigger.
//
// Pure logic: no SystemC, no DMI bus.

#pragma once

#include "hybrid/insn_match.h"

#include <cstddef>
#include <cstdint>
#include <cstring>
#include <optional>
#include <span>
#include <unordered_map>

namespace hybrid
{

struct CsrTriggerHit
{
  hybrid_handoff_kind kind;
  uint32_t insn;
};

class CsrTrigger
{
public:
  void scan_buffer(std::span<const uint8_t> code, uint64_t base_pc)
  {
    std::size_t i = 0;
    while (i + sizeof(uint16_t) <= code.size()) {
      uint16_t lo = 0;
      std::memcpy(&lo, code.data() + i, sizeof(lo));

      const bool is_32 = (lo & 0x3u) == 0x3u;
      if (is_32) {
        if (i + sizeof(uint32_t) > code.size()) break;
        uint32_t insn = 0;
        std::memcpy(&insn, code.data() + i, sizeof(insn));
        hybrid_handoff_kind kind = HYBRID_HANDOFF_NONE;
        if (hybrid_match_handoff_insn(insn, &kind)) {
          hits_.insert_or_assign(base_pc + i, CsrTriggerHit{kind, insn});
        }
        i += sizeof(uint32_t);
      } else {
        i += sizeof(uint16_t);
      }
    }
  }

  // PC-trigger mode: insert a synthetic hit without scanning. Used when the
  // orchestrator passes --hybrid-exit-pc on the CLI; in that case the binary
  // need not contain a marker HINT, and `insn` is unused (HandoffController
  // dispatches on `kind` alone; PC mode only inserts EXIT).
  void add_pc_hit(uint64_t pc, hybrid_handoff_kind kind)
  {
    hits_.insert_or_assign(pc, CsrTriggerHit{kind, /*insn=*/0u});
  }

  auto lookup(uint64_t pc) const -> std::optional<CsrTriggerHit>
  {
    if (auto it = hits_.find(pc); it != hits_.end()) return it->second;
    return std::nullopt;
  }

private:
  std::unordered_map<uint64_t, CsrTriggerHit> hits_;
};

}  // namespace hybrid

// CsrTrigger pre-scans the ELF for the marker HINTs (slti x0, x0,
// 0x5A0/0x5A1) and provides O(1) lookup-by-PC at retire time. Pure logic;
// no SystemC, no DMI bus.

#include "hybrid/csr_trigger.hpp"
#include "hybrid/insn_match.h"
#include "insn_encoders.hpp"

#define DOCTEST_CONFIG_IMPLEMENT_WITH_MAIN
#include <doctest.h>

#include <array>
#include <cstdint>
#include <cstring>
#include <span>

using hybrid::test::as_bytes;
using hybrid::test::encode_slti;

namespace {

constexpr auto encode_addi(uint32_t rd, uint32_t rs1, uint32_t imm) -> uint32_t
{
  return (imm << 20) | (rs1 << 15) | (0u << 12) | (rd << 7) | 0x13u;
}

}  // namespace

TEST_CASE("csr_trigger: scan_buffer records the exit marker as EXIT")
{
  hybrid::CsrTrigger trig;
  const std::array<uint32_t, 1> code{encode_slti(0, 0, 0x5A1)};
  trig.scan_buffer(as_bytes(code), /*base_pc=*/0x80000000);

  const auto hit = trig.lookup(0x80000000);
  REQUIRE(hit);
  CHECK(hit->kind == HYBRID_HANDOFF_EXIT);
}

TEST_CASE("csr_trigger: scan_buffer records the enter marker as ENTER")
{
  hybrid::CsrTrigger trig;
  const std::array<uint32_t, 1> code{encode_slti(0, 0, 0x5A0)};
  trig.scan_buffer(as_bytes(code), /*base_pc=*/0x80000004);

  const auto hit = trig.lookup(0x80000004);
  REQUIRE(hit);
  CHECK(hit->kind == HYBRID_HANDOFF_ENTER);
}

TEST_CASE("csr_trigger: lookup returns nullopt for non-matching PC")
{
  hybrid::CsrTrigger trig;
  const std::array<uint32_t, 1> code{encode_addi(1, 0, 1)};
  trig.scan_buffer(as_bytes(code), /*base_pc=*/0x80000000);

  CHECK_FALSE(trig.lookup(0x80000000).has_value());
  CHECK_FALSE(trig.lookup(0xDEADBEEF).has_value());
}

TEST_CASE("csr_trigger: scan over a multi-insn block records only matches")
{
  hybrid::CsrTrigger trig;
  const std::array<uint32_t, 4> code{
    /*0x80000000*/ encode_addi(1, 0, 1),
    /*0x80000004*/ encode_slti(0, 0, 0x5A0),  // ENTER
    /*0x80000008*/ encode_addi(2, 0, 2),
    /*0x8000000C*/ encode_slti(0, 0, 0x5A1),  // EXIT
  };
  trig.scan_buffer(as_bytes(code), /*base_pc=*/0x80000000);

  CHECK_FALSE(trig.lookup(0x80000000).has_value());
  REQUIRE(trig.lookup(0x80000004));
  CHECK(trig.lookup(0x80000004)->kind == HYBRID_HANDOFF_ENTER);
  CHECK_FALSE(trig.lookup(0x80000008).has_value());
  REQUIRE(trig.lookup(0x8000000C));
  CHECK(trig.lookup(0x8000000C)->kind == HYBRID_HANDOFF_EXIT);
}

TEST_CASE("csr_trigger: add_pc_hit inserts a synthetic EXIT entry for PC mode")
{
  hybrid::CsrTrigger trig;

  trig.add_pc_hit(0x80000042, HYBRID_HANDOFF_EXIT);

  const auto hit = trig.lookup(0x80000042);
  REQUIRE(hit);
  CHECK(hit->kind == HYBRID_HANDOFF_EXIT);
  CHECK(hit->insn == 0u);  // PC mode: insn is unused; sentinel zero
  CHECK_FALSE(trig.lookup(0x80000040).has_value());
}

TEST_CASE("csr_trigger: add_pc_hit overwrites a prior scan_buffer match at same PC")
{
  hybrid::CsrTrigger trig;
  const std::array<uint32_t, 1> code{encode_slti(0, 0, 0x5A1)};
  trig.scan_buffer(as_bytes(code), /*base_pc=*/0x80000100);
  REQUIRE(trig.lookup(0x80000100));
  REQUIRE(trig.lookup(0x80000100)->insn != 0u);

  trig.add_pc_hit(0x80000100, HYBRID_HANDOFF_EXIT);

  const auto hit = trig.lookup(0x80000100);
  REQUIRE(hit);
  CHECK(hit->kind == HYBRID_HANDOFF_EXIT);
  CHECK(hit->insn == 0u);  // overwrite cleared the recorded insn
}

TEST_CASE("csr_trigger: 2-byte stride skips compressed insns and aligns 4-byte insns")
{
  // Layout:
  //   0x80000000: c.addi x1, 1            (2 bytes, RVC: bits[1:0] != 0b11)
  //   0x80000002: slti x0, x0, 0x5A1      (4 bytes)
  //   0x80000006: c.nop                   (2 bytes)
  hybrid::CsrTrigger trig;
  alignas(uint32_t) std::array<uint8_t, 8> bytes{};
  // c.addi x1, 1 = 0x0085 (op=01, funct3=000, rd=x1, imm=1) -- rvc bits[1:0]=01
  // Use a placeholder 16-bit RVC pattern: 0x0085
  bytes[0] = 0x85;
  bytes[1] = 0x00;
  // slti x0, x0, 0x5A1 = 0x5A102013 (little-endian: 13 20 10 5A)
  const uint32_t exit_insn = encode_slti(0, 0, 0x5A1);
  std::memcpy(&bytes[2], &exit_insn, sizeof(exit_insn));
  // c.nop = 0x0001 (rvc bits[1:0]=01)
  bytes[6] = 0x01;
  bytes[7] = 0x00;

  trig.scan_buffer(std::span<const uint8_t>{bytes.data(), bytes.size()},
                   /*base_pc=*/0x80000000);

  // Only the 4-byte marker at 0x80000002 should match.
  CHECK_FALSE(trig.lookup(0x80000000).has_value());
  REQUIRE(trig.lookup(0x80000002));
  CHECK(trig.lookup(0x80000002)->kind == HYBRID_HANDOFF_EXIT);
  CHECK_FALSE(trig.lookup(0x80000006).has_value());
}

